s = SRC.read_text(encoding='utf-8')
for p in PAIRS:
    old, new = p[0], p[1]
    n = p[2] if len(p) > 2 else 1
    c = s.count(old)
    if c != n:
        sys.exit(f'Үзінді {c} рет табылды (күтілгені {n}): {old[:80]}')
    s = s.replace(old, new)
DST.write_text(s, encoding='utf-8')
print(DST.name, 'дайын')
